<?php
declare(strict_types=1);
namespace Sentinel\Tests\Integration;
use PHPUnit\Framework\TestCase;
use Sentinel\Core\HttpException;
use Sentinel\Tests\FieldFixture;
final class WorkforceAssuranceTest extends TestCase
{
    private const PNG='iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAQAAAC1HAwCAAAAC0lEQVR42mP8/x8AAusB9Wl6zAAAAABJRU5ErkJggg==';
    private function rejects(callable $fn,int $status):void {try{$fn();self::fail('Expected rejection');}catch(HttpException $e){self::assertSame($status,$e->statusCode(),$e->getMessage());}}
    private function course($s):string {return $s->create(['site_id'=>1,'title'=>'Gate procedure edition 1','lesson'=>'Check identity, record arrival and keep the exit clear.','quiz'=>[['question'=>'What comes first?','options'=>['Check identity','Open without checking'],'correct'=>0]],'pass_percent'=>100,'valid_days'=>30,'max_attempts'=>2])['id'];}
    private function property($s):string {return $s->create(['site_id'=>1,'description'=>'Blue bag','found_location'=>'Gate desk','storage_location'=>'Locker A','found_at'=>gmdate('Y-m-d H:i:s'),'photo_base64'=>self::PNG])['id'];}
    private function stock($s):string {return $s->create(['site_id'=>1,'sku'=>'SHIRT','item_name'=>'Uniform shirt','item_size'=>'L','category'=>'UNIFORM','reorder_level'=>2])['id'];}
    private function incident($db,int $id=1,int $site=1):void {$db->execute("INSERT INTO incidents(incident_id,incident_uuid,company_id,site_id,incident_number,incident_type,incident_category,description,occurred_at) VALUES(:id,:uuid,101,:site,:number,'GATE','SECURITY','Gate incident',:now)",['id'=>$id,'uuid'=>uuid4(),'site'=>$site,'number'=>'INC-'.$id,'now'=>gmdate('Y-m-d H:i:s')]);}
    public function testLearningServerGradesHidesAnswersAndRetriesWithoutDuplicateCertificates():void {
        [$app,$db,$ctx]=FieldFixture::create();$s=$app->container()->make('learning_portal_service');$id=$this->course($s);$this->rejects(fn()=>$s->assign($id,['employee_id'=>2,'due_on'=>gmdate('Y-m-d')]),422);$s->publish($id);$assignment=$s->assign($id,['employee_id'=>2,'due_on'=>gmdate('Y-m-d')])['id'];$this->rejects(fn()=>$s->readLesson($assignment,['read'=>true,'content_hash'=>'wrong']),404);$ctx->setUser('2');$course=$s->list([],true)[0];self::assertArrayNotHasKey('correct',$course['quiz'][0]);$body=['operation_uuid'=>uuid4(),'content_hash'=>$course['content_hash'],'answers'=>[0]];$this->rejects(fn()=>$s->submit($assignment,$body),409);$s->readLesson($assignment,['read'=>true,'content_hash'=>$course['content_hash']]);$fail=$s->submit($assignment,[...$body,'answers'=>[1]]);self::assertFalse($fail['passed']);$body['operation_uuid']=uuid4();self::assertTrue($s->submit($assignment,$body)['passed']);self::assertTrue($s->submit($assignment,$body)['passed']);$this->rejects(fn()=>$s->submit($assignment,[...$body,'answers'=>[1]]),409);self::assertSame(1,(int)$db->fetch('SELECT COUNT(*) AS n FROM learning_certificates')['n']);self::assertSame(0,(int)$db->fetch('SELECT COUNT(*) AS n FROM employee_training')['n']);$cert=$s->list([],true)[0]['assignments'][0];self::assertSame('CURRENT',$cert['certificate_state']);$ctx->setUser('1');$s->revoke((string)$cert['certificate_id'],['reason'=>'Retraining required']);$ctx->setUser('2');self::assertSame('REVOKED',$s->list([],true)[0]['assignments'][0]['certificate_state']);
    }
    public function testLearningAttemptLimitAndPayloadValidation():void {
        [$app,$db,$ctx]=FieldFixture::create();$s=$app->container()->make('learning_portal_service');$id=$this->course($s);$s->publish($id);$a=$s->assign($id,['employee_id'=>2,'due_on'=>gmdate('Y-m-d')])['id'];$hash=$s->list(['site_id'=>1])[0]['content_hash'];$ctx->setUser('2');$s->readLesson($a,['read'=>true,'content_hash'=>$hash]);for($i=0;$i<2;$i++)self::assertFalse($s->submit($a,['operation_uuid'=>uuid4(),'content_hash'=>$hash,'answers'=>[1]])['passed']);$this->rejects(fn()=>$s->submit($a,['operation_uuid'=>uuid4(),'content_hash'=>$hash,'answers'=>[0]]),409);$this->rejects(fn()=>$s->submit($a,['operation_uuid'=>uuid4(),'content_hash'=>$hash,'answers'=>[0],'score_percent'=>100]),422);self::assertSame(0,(int)$db->fetch('SELECT COUNT(*) AS n FROM learning_certificates')['n']);
    }
    public function testFoundPropertyPhotoMovementSignedReceiptAndNoDoubleCollection():void {
        [$app,$db,$ctx]=FieldFixture::create();$s=$app->container()->make('found_property_service');$id=$this->property($s);self::assertSame(self::PNG,$s->photo($id)['base64']);$s->action($id,'move',['expected_revision'=>1,'storage_location'=>'Safe B','notes'=>'Witnessed transfer']);$body=['expected_revision'=>2,'claimant_name'=>'Owner','identity_checked'=>true,'signature_base64'=>self::PNG,'notes'=>'Description and identity checked'];$this->rejects(fn()=>$s->action($id,'collect',[...$body,'identity_checked'=>false]),422);self::assertSame('COLLECTED',$s->action($id,'collect',$body)['state']);$this->rejects(fn()=>$s->action($id,'collect',$body),409);$receipt=$s->receipt($id);self::assertCount(1,$receipt['collections']);self::assertSame('Safe B',$receipt['item']['storage_location']);$ctx->setTenantId(202);$ctx->setUser('3');$this->rejects(fn()=>$s->receipt($id),404);
    }
    public function testFoundPropertyRejectsInvalidImagesAndCorruptStoredPhoto():void {
        [$app,$db]=FieldFixture::create();$s=$app->container()->make('found_property_service');$this->rejects(fn()=>$s->create(['site_id'=>1,'description'=>'x','found_location'=>'x','storage_location'=>'x','found_at'=>gmdate('Y-m-d H:i:s'),'photo_base64'=>base64_encode('<svg onload=alert(1)>')]),422);$id=$this->property($s);$db->execute("UPDATE found_property SET photo_base64='corrupt'");$this->rejects(fn()=>$s->photo($id),409);
    }
    public function testStockLedgerIdempotencyAcceptancePartialReturnAndWriteoff():void {
        [$app,$db,$ctx]=FieldFixture::create();$s=$app->container()->make('stock_uniform_service');$id=$this->stock($s);$receive=['operation_uuid'=>uuid4(),'quantity'=>5,'notes'=>'Delivery note 123'];self::assertSame(5,$s->movement($id,'receive',$receive)['available_quantity']);self::assertSame(5,$s->movement($id,'receive',$receive)['available_quantity']);$this->rejects(fn()=>$s->movement($id,'receive',[...$receive,'quantity'=>6]),409);$issue=['operation_uuid'=>uuid4(),'quantity'=>3,'notes'=>'Checked uniform size','employee_id'=>2,'due_at'=>gmdate('Y-m-d H:i:s',time()+86400)];$r=$s->movement($id,'issue',$issue);$a=$r['allocation_id'];self::assertSame(2,$r['available_quantity']);$this->rejects(fn()=>$s->movement($id,'issue',[...$issue,'operation_uuid'=>uuid4()]),409);$this->rejects(fn()=>$s->accept($a,['expected_revision'=>1,'signature_base64'=>self::PNG]),404);$ctx->setUser('2');self::assertTrue($s->accept($a,['expected_revision'=>1,'signature_base64'=>self::PNG])['accepted']);self::assertCount(1,$s->list([],true));$ctx->setUser('1');$s->movement($id,'return',['operation_uuid'=>uuid4(),'quantity'=>2,'allocation_id'=>$a,'condition'=>'RESTOCK','notes'=>'Physically counted, clean return']);$last=$s->movement($id,'writeoff',['operation_uuid'=>uuid4(),'quantity'=>1,'allocation_id'=>$a,'condition'=>'LOST','notes'=>'Approved loss reference 1']);self::assertSame('SETTLED',$last['state']);self::assertSame(4,$last['available_quantity']);$this->rejects(fn()=>$s->movement($id,'return',['operation_uuid'=>uuid4(),'quantity'=>1,'allocation_id'=>$a,'condition'=>'RESTOCK','notes'=>'Duplicate return']),409);self::assertSame(self::PNG,$s->receipt($a)['allocation']['signature_base64']);self::assertSame(1,(int)$db->fetch("SELECT affected_quantity FROM stock_movements WHERE movement_type='WRITE_OFF'")['affected_quantity']);self::assertSame(0,$s->movement($id,'adjust',['operation_uuid'=>uuid4(),'quantity'=>0,'notes'=>'Physical stock count discrepancy investigated'])['available_quantity']);
    }
    public function testPendingStockCancellationRestoresOnlyOnceAndQuarantineDoesNotRestock():void {
        [$app,$db,$ctx]=FieldFixture::create();$s=$app->container()->make('stock_uniform_service');$id=$this->stock($s);$s->movement($id,'receive',['operation_uuid'=>uuid4(),'quantity'=>2,'notes'=>'Received']);$a=$s->movement($id,'issue',['operation_uuid'=>uuid4(),'quantity'=>2,'employee_id'=>2,'due_at'=>gmdate('Y-m-d H:i:s',time()+3600),'notes'=>'Issue'])['allocation_id'];$cancel=['operation_uuid'=>uuid4(),'allocation_id'=>$a,'notes'=>'Recipient unavailable'];self::assertSame(2,$s->movement($id,'cancel',$cancel)['available_quantity']);self::assertSame(2,$s->movement($id,'cancel',$cancel)['available_quantity']);$ctx->setUser('2');$this->rejects(fn()=>$s->accept($a,['expected_revision'=>1,'signature_base64'=>self::PNG]),409);$ctx->setUser('1');$a=$s->movement($id,'issue',['operation_uuid'=>uuid4(),'quantity'=>1,'employee_id'=>2,'due_at'=>gmdate('Y-m-d H:i:s',time()+3600),'notes'=>'Issue replacement'])['allocation_id'];$ctx->setUser('2');$s->accept($a,['expected_revision'=>1,'signature_base64'=>self::PNG]);$ctx->setUser('1');self::assertSame(1,$s->movement($id,'return',['operation_uuid'=>uuid4(),'allocation_id'=>$a,'quantity'=>1,'condition'=>'QUARANTINE','notes'=>'Damaged, stored separately'])['available_quantity']);
    }
    private function caseFixture():array {[$app,$db,$ctx]=FieldFixture::create();$db->execute('INSERT INTO user_roles VALUES(2,1,101)');$this->incident($db);$s=$app->container()->make('investigation_case_service');$id=$s->create(['incident_id'=>1,'investigator_user_id'=>2,'due_on'=>gmdate('Y-m-d'),'notes'=>'Preserve originals and review gate response'])['id'];return [$app,$db,$ctx,$s,$id];}
    private function revision($s):int {return (int)$s->list(['site_id'=>1])[0]['revision'];}
    public function testInvestigationsRequireActionsRootCauseAndIndependentClosure():void {
        [$app,$db,$ctx,$s,$id]=$this->caseFixture();$s->transition($id,'begin',['expected_revision'=>1,'notes'=>'Investigation started']);$ctx->setUser('2');$this->rejects(fn()=>$s->transition($id,'submit',['expected_revision'=>2,'notes'=>'Incomplete summary']),409);$s->note($id,['note_type'=>'ROOT_CAUSE','notes'=>'Handover procedure missing']);$e=$s->upload($id,['original_filename'=>'notes.txt','file_base64'=>base64_encode('Original witness account'),'description'=>'Witness evidence','captured_at'=>gmdate('Y-m-d H:i:s')]);self::assertSame(base64_encode('Original witness account'),$s->original($id,$e['id'])['base64']);$a=$s->action($id,['title'=>'Review handover procedure','owner_user_id'=>2,'due_on'=>gmdate('Y-m-d')])['id'];$this->rejects(fn()=>$s->transition($id,'submit',['expected_revision'=>$this->revision($s),'notes'=>'Summary']),409);$ctx->setUser('1');$this->rejects(fn()=>$s->complete($a,['expected_revision'=>1,'notes'=>'Claim someone else completed it']),403);$ctx->setUser('2');$s->complete($a,['expected_revision'=>1,'notes'=>'Procedure reviewed and staff briefed']);$s->transition($id,'submit',['expected_revision'=>$this->revision($s),'notes'=>'Root cause and corrective action reviewed']);$r=$s->list(['site_id'=>1])[0];$this->rejects(fn()=>$s->note($id,['note_type'=>'FINDING','notes'=>'Edit during review']),409);$this->rejects(fn()=>$s->transition($id,'approve',['expected_revision'=>$r['revision'],'notes'=>'Self approval','expected_hash'=>$r['review_hash']]),403);$ctx->setUser('1');self::assertSame('CLOSED',$s->transition($id,'approve',['expected_revision'=>$r['revision'],'notes'=>'Independent review completed','expected_hash'=>$r['review_hash']])['state']);self::assertNull($db->fetch('SELECT released_at FROM retention_holds')['released_at']);self::assertSame('OPEN',$db->fetch('SELECT status FROM incidents')['status']);self::assertSame('INVESTIGATING',$s->transition($id,'reopen',['expected_revision'=>$this->revision($s),'notes'=>'New evidence reported'])['state']);
    }
    public function testInvestigationChangedIncidentBlocksStaleReviewAndUnrelatedEvidence():void {
        [$app,$db,$ctx,$s,$id]=$this->caseFixture();$this->incident($db,2,2);$e=$app->container()->make('evidence_retention_service')->addEvidence(['incident_id'=>2,'original_filename'=>'other.txt','file_base64'=>base64_encode('unrelated'),'description'=>'Other incident','captured_at'=>gmdate('Y-m-d H:i:s')]);$this->rejects(fn()=>$s->note($id,['note_type'=>'EVIDENCE','notes'=>'Wrong incident','evidence_id'=>$e['id']]),404);$s->transition($id,'begin',['expected_revision'=>1,'notes'=>'Started']);$s->note($id,['note_type'=>'ROOT_CAUSE','notes'=>'Recorded root cause']);$ctx->setUser('2');$s->transition($id,'submit',['expected_revision'=>$this->revision($s),'notes'=>'Summary']);$r=$s->list(['site_id'=>1])[0];$db->execute("UPDATE incidents SET description='Revised account' WHERE incident_id=1");$ctx->setUser('1');$this->rejects(fn()=>$s->transition($id,'approve',['expected_revision'=>$r['revision'],'notes'=>'Approve stale','expected_hash'=>$r['review_hash']]),409);self::assertSame('INVESTIGATING',$s->transition($id,'return',['expected_revision'=>$r['revision'],'notes'=>'Review the revised account'])['state']);
    }
    public function testNewWorkspacesEnforceRestrictedSiteAndTenantBoundaries():void {
        [$app,$db,$ctx]=FieldFixture::create();$found=$app->container()->make('found_property_service');$id=$this->property($found);$stock=$app->container()->make('stock_uniform_service');$sid=$this->stock($stock);$db->execute("INSERT INTO permissions VALUES(9001,101,'site_scope.restricted','ACTIVE')");$db->execute('INSERT INTO role_permissions VALUES(1,9001,101)');$this->rejects(fn()=>$found->photo($id),404);$this->rejects(fn()=>$stock->list(['site_id'=>1]),404);$db->execute('INSERT INTO user_site_grants(company_id,user_id,site_id,granted_by_user_id,granted_at) VALUES(101,1,1,1,:now)',['now'=>gmdate('Y-m-d H:i:s')]);self::assertCount(1,$found->list(['site_id'=>1]));$this->rejects(fn()=>$found->list(['site_id'=>2]),404);$ctx->setTenantId(202);$ctx->setUser('3');$this->rejects(fn()=>$found->photo($id),404);$this->rejects(fn()=>$stock->movement($sid,'receive',['operation_uuid'=>uuid4(),'quantity'=>1,'notes'=>'Wrong tenant']),404);
    }
    public function testAuditFailureRollsBackStockAndPropertyState():void {
        [$app,$db]=FieldFixture::create();$s=$app->container()->make('stock_uniform_service');$id=$this->stock($s);$db->execute("CREATE TRIGGER reject_audit BEFORE INSERT ON audit_logs BEGIN SELECT RAISE(FAIL,'audit blocked'); END");try{$s->movement($id,'receive',['operation_uuid'=>uuid4(),'quantity'=>10,'notes'=>'Delivery']);self::fail('Expected failure');}catch(\PDOException){}self::assertSame(0,(int)$db->fetch('SELECT available_quantity FROM stock_items')['available_quantity']);self::assertSame(0,(int)$db->fetch('SELECT COUNT(*) AS n FROM stock_movements')['n']);
    }
    public function testCertificateAndStockRemindersDeduplicateAndClear():void {
        [$app,$db,$ctx]=FieldFixture::create();$db->execute('CREATE TABLE contracts(contract_id INTEGER,company_id INTEGER,end_date TEXT,status TEXT,deleted_at TEXT)');$learning=$app->container()->make('learning_portal_service');$course=$this->course($learning);$learning->publish($course);$a=$learning->assign($course,['employee_id'=>2,'due_on'=>gmdate('Y-m-d')])['id'];$hash=$learning->list(['site_id'=>1])[0]['content_hash'];$ctx->setUser('2');$learning->readLesson($a,['read'=>true,'content_hash'=>$hash]);$learning->submit($a,['operation_uuid'=>uuid4(),'content_hash'=>$hash,'answers'=>[0]]);$ctx->setUser('1');$stock=$app->container()->make('stock_uniform_service');$this->stock($stock);$app->container()->make('pilot_setup_service')->settings(['reminder_user_id'=>1,'expected_revision'=>0]);$r=$app->container()->make('business_reminder_service');self::assertSame(2,$r->tick()['reminders']);self::assertSame(0,$r->tick()['reminders']);self::assertCount(2,$r->list());$learning->revoke('1',['reason'=>'Replaced by assessed refresher']);$stock->movement('1','receive',['operation_uuid'=>uuid4(),'quantity'=>3,'notes'=>'Replenished']);$r->tick();self::assertSame(['RESOLVED'],array_values(array_unique(array_column($r->list(),'state'))));
    }
    public function testInvestigationHandoverChangesWhoMaySubmitAndAttest():void {
        [$app,$db,$ctx,$s,$id]=$this->caseFixture();$s->transition($id,'begin',['expected_revision'=>1,'notes'=>'Started']);$s->note($id,['note_type'=>'ROOT_CAUSE','notes'=>'Recorded cause']);$a=$s->action($id,['title'=>'Brief staff','owner_user_id'=>2,'due_on'=>gmdate('Y-m-d')])['id'];$s->reassign($id,['expected_revision'=>$this->revision($s),'investigator_user_id'=>1,'due_on'=>gmdate('Y-m-d'),'notes'=>'Cover investigator absence']);$s->reassignAction($a,['expected_revision'=>1,'owner_user_id'=>1,'due_on'=>gmdate('Y-m-d'),'notes'=>'Handover action to covering operator']);$ctx->setUser('2');$this->rejects(fn()=>$s->complete($a,['expected_revision'=>2,'notes'=>'Former owner']),403);$this->rejects(fn()=>$s->transition($id,'submit',['expected_revision'=>$this->revision($s),'notes'=>'Former investigator']),403);$ctx->setUser('1');$s->complete($a,['expected_revision'=>2,'notes'=>'Briefing completed']);self::assertSame('REVIEW',$s->transition($id,'submit',['expected_revision'=>$this->revision($s),'notes'=>'Covering investigator summary'])['state']);$this->rejects(fn()=>$s->reassign($id,['expected_revision'=>$this->revision($s),'investigator_user_id'=>2,'due_on'=>gmdate('Y-m-d'),'notes'=>'Edit frozen review']),409);
    }
}
